import { SHARED_SUBDIR } from '../../engine/pack_loader/pack-registry.mjs';

// Consumers must not couple to the vendored canon (vendoring/DESIGN.md): outside
// the wiring set, no file may reference .claudinite/ — product code that wants
// a canon helper inlines it, because depending on canon internals turns every
// canon refactor into a breaking migration for code the canon doesn't own.
//
// A CONTRIBUTED barrier: this module is pure data the barriers pack builds
// into the rule (basics `requires` barriers and carries this under
// `contributes` on its manifest — the declaration-and-configuration
// composition pack-independence mandates, replacing the old code-composed
// defineBarrier import). `gateDir` keeps it inert until the vendored mount
// exists (.claudinite/shared/) — so it never fires in the canon repo or in
// pre-flip consumers.
//
// The wiring carve-outs — the files that legitimately spell .claudinite/ paths:
// - '.claudinite': the mount subtree itself (local/packs/ referencing the canon;
//   the vendored files are already outside the scanned set).
// - '.claude': settings.json registers the hooks by path.
// - '.github/workflows': a repo's own workflow may run the vendored engine.
// - '.gitignore', '.gitattributes': the mount's housekeeping rules.
// - '.claudinite-checks.json': settings legitimately spell paths.
// Coverage note: quoted references (imports, requires, config values) and
// relative traversals resolve and fire; a bare unquoted `.claudinite/...` in
// prose falls outside the engine's candidate shapes — accepted, since
// imports/wiring are the coupling class that matters.
export default {
  id: 'claudinite-isolation',
  // CLAUDE.md was a wiring exception until #384: a consumer's CLAUDE.md carried an
  // `@.claudinite/shared/CLAUDE.md` import, a real reference into the mount that the
  // carve-out existed to permit. #384 retired that import and had converge-wiring
  // strip it (`removeRetiredCorpusImport`), removing the only reason a consumer's
  // CLAUDE.md needs to name the mount — so the carve-out went with it, deliberately.
  // This description said otherwise for far longer than it should have, and the gap
  // fired on canon-shaped orientation prose across the fleet.
  description: 'Outside the wiring files (.claude/, .gitignore, .gitattributes, .github/workflows/, the settings file), nothing may reference .claudinite/ — CLAUDE.md included — inline what you need instead of importing the canon',
  why: 'the vendored canon is refreshed nightly and refactored upstream; code that reaches into it inherits every canon rename as a breaking change',
  doc: 'vendoring/DESIGN.md',
  // The remedy is to stop depending on the canon, not to relocate the
  // dependency: there is no shared folder both sides may use (the mount is
  // one-directional), and the canon is not the consumer's to restructure. The
  // engine's default first clause would say "route shared code through a
  // shared/contracts folder", which no consumer can act on.
  crossingRemedy: 'inline what you need into your own tree (copy the few lines; the canon is refreshed nightly and is not yours to depend on)',
  crossingExcuse: 'if the crossing is deliberate, excuse it with accept: [{ "rule": "claudinite-isolation", "path": "<file>", "reason": "..." }] in .claudinite-checks.json (a pack-shipped barrier takes no per-rule except entries)',
  gateDir: SHARED_SUBDIR,
  edges: [{
    from: '.',
    to: '.claudinite',
    matchUniqueFilenames: false,
    except: ['.claudinite', '.claude', '.github/workflows', '.gitignore', '.gitattributes', '.claudinite-checks.json'],
    reason: 'consumer files must not couple to the vendored canon — the wiring files are the reviewed exceptions (vendoring/DESIGN.md)',
  }],
};

import { spawnSync } from 'node:child_process';
import { readFileSync, existsSync, statSync } from 'node:fs';
import { join, resolve, sep } from 'node:path';
import { parseEntries } from './session-transcript.mjs';
import { SHARED_SUBDIR, packEntryId } from '../../pack_loader/pack-registry.mjs';

function sh(root, cmd, args, { allowFail = false, input = undefined, timeout = undefined } = {}) {
  const r = spawnSync(cmd, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, input, timeout });
  if (r.status !== 0 && !allowFail) {
    throw new Error(`${cmd} ${args.join(' ')} failed (${r.status}): ${r.stderr}`);
  }
  return r.status === 0 ? r.stdout : null;
}

const git = (root, ...args) => sh(root, 'git', args);
const gitTry = (root, ...args) => sh(root, 'git', args, { allowFail: true });

function resolveBaseRef(root) {
  for (const ref of ['origin/main', 'origin/master', 'main', 'master']) {
    if (gitTry(root, 'rev-parse', '--verify', '--quiet', `${ref}^{commit}`) !== null) return ref;
  }
  return null;
}

const FETCH_TIMEOUT_MS = 8000;

// A remote-tracking base ref is only as fresh as the last fetch, and a cloud session's
// clone freezes it at container-creation time — so every commit the base branch gained
// since lands inside `mergeBase..HEAD` and gets billed to the work. That is a wrong
// verdict, not a stale one: the delta rules (squash-merge-history above all, a *blocking*
// rule) report other people's commits as introduced by this change, and `--changed`
// widens to files the change never touched. Refreshing the ref once per run is what makes
// "the work" mean the work.
//
// Best-effort by construction — no network, no remote, a lock held, a slow server: the
// fetch fails or times out and the run continues against the ref as it stands, exactly as
// before this existed. It writes ONLY the remote-tracking ref (explicit refspec, no tags):
// no local branch, no index, no working tree, nothing the session could be surprised by.
// Set CLAUDINITE_CHECKS_NO_FETCH=1 to skip it (sealed sandboxes, or to pin a base).
function refreshBaseRef(root, ref) {
  if (!ref || process.env.CLAUDINITE_CHECKS_NO_FETCH === '1') return;
  const m = /^([^/]+)\/(.+)$/.exec(ref);
  if (!m) return; // a local branch is already as current as the checkout — nothing to fetch
  const [, remote, branch] = m;
  sh(root, 'git', ['fetch', '--quiet', '--no-tags', remote,
    `+refs/heads/${branch}:refs/remotes/${remote}/${branch}`],
  { allowFail: true, timeout: FETCH_TIMEOUT_MS });
}

function lines(out) {
  return (out || '').split('\n').filter(Boolean);
}

// Files git marks vendored or generated (linguist-vendored / linguist-generated in
// .gitattributes) — third-party or machine-written content, not the project's own
// code. `buildContext` drops these from the default `ctx.files`, so every check that
// reasons about "the project's code" skips them for free: a suppression marker inside
// a recorded fixture, a placement "violation" in a generated artifact, and a dangling
// link in a vendored doc are none of them the project's decision. `git check-attr`
// honors .gitattributes patterns/precedence natively (paths on stdin so a large repo
// can't overflow the arg list). The unfiltered set stays on `ctx.allFiles` for the one
// check that reasons *about* generated files (generated-merge-driver).
function vendoredSet(root, files) {
  const set = new Set();
